fetch("/api/premium/login", {
    method: "POST",
    headers: {
        "Content-Type": "application/json",
    },
    body: JSON.stringify({ password }),
})

fetch(edinetIdentityUatUrl(url), {
    method: "GET",
    cache: "no-store",
    credentials: "omit",
    headers: {
        apikey: anonKey,
        Authorization: `Bearer ${session.access_token}`,
        Accept: "application/json",
    },
})

onSubmit={e => {
        e.preventDefault();
        setError("");
        try {
            const command = rewardAction(snapshot, reward, kind, { value, reason, mode, unit, eventId });
            if (["delete", "mode", "remove", "adjust"].includes(kind) && !window.confirm(`${reward.title}: ${warning}`))
                return;
            onSave(command);
        }
        catch (e) {
            setError((e as Error).message);
        }
    }}

onSubmit={e => {
        e.preventDefault();
        setError("");
        try {
            onSave(saveReward(snapshot, reward, { ...fields, unit_yen: mode === "count" && unit.trim() ? rewardNumber(unit, "amount") : null }, { mode, initial, profileId, cycleId }));
        }
        catch (e) {
            setError((e as Error).message);
        }
    }}

fetch(`${env.url}/rest/v1/rpc/stock_notes_get_yutai_reward_totals`, {
    method: "POST", headers: { apikey: env.anonKey, Authorization: `Bearer ${data.session.access_token}`, "Content-Type": "application/json" },
    body: JSON.stringify({ p_today: localToday() }), signal: abort.current.signal,
})

onSubmit={event => {
        event.preventDefault();
        setError("");
        try {
            const quantity = rewardNumber(String(draft.quantity ?? ""), "count", true);
            const fields = { ...rewardFields(), title: draft.title ?? "", company: draft.company ?? "", expires_on: draft.expiresOn,
                unit_yen: draft.amountYen === null ? null : rewardNumber(String(draft.amountYen), "amount") };
            const validated = saveReward(captured, null, fields, { mode: "count", initial: String(quantity), profileId: null, cycleId: null })!;
            const existing = captured.rewards.find(r => r.id === target);
            if (target && (!existing || existing.archived_at || existing.track_mode !== "count"))
                throw new Error("統合対象を選び直してください。");
            if (existing && (existing.expires_on !== fields.expires_on || existing.unit_yen !== fields.unit_yen))
                throw new Error("期限・額面が異なる優待には統合できません。別の優待として追加してください。");
            if (!window.confirm(existing ? `${existing.title}へ${quantity}枚を補充します。既存メモと履歴は残ります。` : `${fields.title}を${quantity}枚で新規登録します。既存の優待は変更しません。`))
                return;
            onSave(existing ? { command_type: "restock_reward", target: { id: existing.id }, expected_revision: existing.revision,
                payload: { value: quantity }, note: "画像スキャン結果を確認して補充" } : validated);
            setDraft(null);
        }
        catch (cause) {
            setError((cause as Error).message);
        }
    }}

fetch("/api/yutai-expiry/scan", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ imageBase64: base64, mimeType }),
})

onSubmit={e => {
        e.preventDefault();
        try {
            onSave(saveCycle(snapshot, profileId, original, { ...draft, quantity: quantity.trim() ? Number(quantity) : null }));
        }
        catch (e) {
            setError((e as Error).message);
        }
    }}

onSubmit={e => {
        e.preventDefault();
        try {
            onSave(saveMonth(original, profile.id, month, { ...draft,
                required_shares: optionalNumber(shares, "株数"), benefit_value_yen: optionalNumber(value, "優待価値"),
                preparation_months_before: optionalNumber(lead, "仕込み開始", true) }));
        }
        catch (e) {
            setError((e as Error).message);
        }
    }}

onSubmit={e => { e.preventDefault(); try {
    onSave(saveProfile(original, code, draft));
}
catch (e) {
    setError((e as Error).message);
} }}

fetch("/api/nikko/short-balance", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ codes: visibleCodes }),
})
